-- ==================================================================
-- Supabase setup for: AAST Campus Walks  (version 1.1)
-- Generated by Questionnaire Designer on 2026-11-06
-- Paste the whole file into Supabase > SQL Editor > New query > Run.
-- Safe to run again: answers are never deleted; views and map tables are rebuilt.
--
-- What you get (export any of them as CSV from Table Editor):
--   campus_walks_respondents       one row per person, readable answers, code R0001, R0002...
--   campus_walks_answers           one row per person, every answer in words (option text, not codes), in questionnaire order
--   campus_walks_agents            one row per person, agent-persona attributes for the ABM
--   campus_walks_routes            one row per walk: ordered segment list + WKT line for QGIS
--   campus_walks_route_segments    one row per segment walked, in order (flows / GNN edges)
--   campus_walks_path_ratings      one row per person per rated path
--   campus_walks_segment_means     per segment: number of raters, mean and SD of each rating, WKT
--   campus_walks_respondent_means  per person: mean of their path ratings
--   campus_walks_segments / campus_walks_places  the campus network from MapThemeUI, with WKT
--   campus_walks_landmarks         the Landmarks layer (stars), with WKT
--   campus_walks_route_landmarks   one row per landmark a person used on a walk (order, nearest route step, distance)
--   campus_walks_landmark_use      per landmark: how often it was used on walks and named in landmark questions
--   campus_walks_border            the Border layer (outline of the site), with WKT
-- ==================================================================

-- 1. Answers table: one row per submitted questionnaire.
create table if not exists public."campus_walks" (
  id uuid primary key default gen_random_uuid(),
  respondent_no bigint generated always as identity,
  created_at timestamptz not null default now(),
  questionnaire_version text,
  data jsonb not null check (jsonb_typeof(data) = 'object' and octet_length(data::text) < 400000)
);
alter table public."campus_walks" add column if not exists respondent_no bigint generated always as identity;
create unique index if not exists "campus_walks_respondent_no_key" on public."campus_walks" (respondent_no);

-- 2. Security: visitors may ONLY insert. They cannot read, change or delete anything.
alter table public."campus_walks" enable row level security;
drop policy if exists "Anyone can submit" on public."campus_walks";
create policy "Anyone can submit" on public."campus_walks" for insert to anon, authenticated with check (true);
revoke all on public."campus_walks" from anon, authenticated;
grant insert (questionnaire_version, data) on public."campus_walks" to anon, authenticated;

-- Remove views from older versions of this file (they are rebuilt below).
drop view if exists public."campus_walks_flat" cascade;
drop view if exists public."campus_walks_agents" cascade;
drop view if exists public."campus_walks_respondents" cascade;
drop view if exists public."campus_walks_routes" cascade;
drop view if exists public."campus_walks_route_segments" cascade;
drop view if exists public."campus_walks_route_landmarks" cascade;
drop view if exists public."campus_walks_landmark_use" cascade;
drop view if exists public."campus_walks_path_ratings" cascade;
drop view if exists public."campus_walks_segment_means" cascade;
drop view if exists public."campus_walks_respondent_means" cascade;
drop view if exists public."campus_walks_walks_trips" cascade;
drop view if exists public."campus_walks_walks_ratings" cascade;
drop view if exists public."campus_walks_walks_segment_means" cascade;

-- 3. Campus network from MapThemeUI. Geometry is WKT in the CRS of your shapefile (unknown).
drop table if exists public."campus_walks_segments" cascade;
create table public."campus_walks_segments" (
  segment_id text primary key,
  from_node text, to_node text,
  length_m numeric, segment_type text, segment_name text, entity_hand text,
  coords_ab text, coords_ba text, coords_ab_tail text, coords_ba_tail text,
  wkt text
);
drop table if exists public."campus_walks_places" cascade;
create table public."campus_walks_places" (place_id text primary key, place_name text, place_type text, node_id text, origin_destination boolean, landmark boolean, entity_hand text, wkt text);
drop table if exists public."campus_walks_captions" cascade;
create table public."campus_walks_captions" (caption_id text primary key, text_en text, text_ar text, wkt text);
