-- 4. One row per respondent, readable answers. Export this as your main CSV.
create view public."campus_walks_respondents" as
select
  'R' || lpad(r.respondent_no::text, 4, '0') as respondent_code,
  r.respondent_no,
  r.created_at as submitted_at,
  round(nullif(r.data->'meta'->>'duration_s','')::numeric / 60, 1) as duration_min,
  r.questionnaire_version,
  r.data->'answers'->>'age' as "age",
  r.data->'answers'->>'sex' as "sex",
  r.data->'answers'->>'role' as "role",
  r.data->'answers'->>'ug_stage' as "ug_stage",
  r.data->'answers'->>'pg_level' as "pg_level",
  r.data->'answers'->>'academic_rank' as "academic_rank",
  r.data->'answers'->>'staff_type' as "staff_type",
  r.data->'answers'->>'visit_purpose' as "visit_purpose",
  r.data->'answers'->>'qualification' as "qualification",
  r.data->'answers'->>'programme' as "programme",
  r.data->'answers'->>'which_programme_are_you_stud' as "which_programme_are_you_stud",
  r.data->'answers'->>'which_faculty_or_building_do' as "which_faculty_or_building_do",
  r.data->'answers'->>'arrival_mode' as "arrival_mode",
  r.data->'answers'->>'arrival_clock' as "arrival_clock",
  r.data->'answers'->>'leave_clock' as "leave_clock",
  r.data->'answers'->>'days_per_week' as "days_per_week",
  r.data->'answers'->>'walks_per_day' as "walks_per_day",
  r.data->'answers'->>'walk_company' as "walk_company",
  r.data->'answers'->>'walk_pace' as "walk_pace",
  (select string_agg(x, '; ') from jsonb_array_elements_text(case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end) as x) as "visual_features",
  (case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end @> to_jsonb('greenery'::text))::int as "visual_features_greenery",
  (case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end @> to_jsonb('facades'::text))::int as "visual_features_facades",
  (case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end @> to_jsonb('signs'::text))::int as "visual_features_signs",
  (case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end @> to_jsonb('art'::text))::int as "visual_features_art",
  (case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end @> to_jsonb('people'::text))::int as "visual_features_people",
  (case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end @> to_jsonb('views'::text))::int as "visual_features_views",
  (case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end @> to_jsonb('shade'::text))::int as "visual_features_shade",
  (case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end @> to_jsonb('water'::text))::int as "visual_features_water",
  nullif(r.data->'answers'->'legibility'->>'leg1','')::numeric as "legibility_leg1",
  nullif(r.data->'answers'->'legibility'->>'leg2','')::numeric as "legibility_leg2",
  nullif(r.data->'answers'->'legibility'->>'int1','')::numeric as "legibility_int1",
  nullif(r.data->'answers'->'legibility'->>'int2','')::numeric as "legibility_int2",
  nullif(r.data->'answers'->'lrs'->>'lost','')::numeric as "lrs_lost",
  nullif(r.data->'answers'->'lrs'->>'l1','')::numeric as "lrs_l1",
  nullif(r.data->'answers'->'lrs'->>'l2','')::numeric as "lrs_l2",
  nullif(r.data->'answers'->'lrs'->>'r1','')::numeric as "lrs_r1",
  nullif(r.data->'answers'->'lrs'->>'r2','')::numeric as "lrs_r2",
  nullif(r.data->'answers'->'lrs'->>'s1','')::numeric as "lrs_s1",
  nullif(r.data->'answers'->'lrs'->>'s2','')::numeric as "lrs_s2",
  nullif(r.data->'answers'->'cue'->>'signs','')::numeric as "cue_signs",
  nullif(r.data->'answers'->'cue'->>'landmarks','')::numeric as "cue_landmarks",
  nullif(r.data->'answers'->'cue'->>'maps','')::numeric as "cue_maps",
  nullif(r.data->'answers'->'cue'->>'people','')::numeric as "cue_people",
  nullif(r.data->'answers'->'cue'->>'memory','')::numeric as "cue_memory",
  nullif(r.data->'answers'->'rc'->>'distance','')::numeric as "rc_distance",
  nullif(r.data->'answers'->'rc'->>'angular','')::numeric as "rc_angular",
  nullif(r.data->'answers'->'rc'->>'turns','')::numeric as "rc_turns",
  nullif(r.data->'answers'->'rc'->>'shade','')::numeric as "rc_shade",
  nullif(r.data->'answers'->'rc'->>'surface','')::numeric as "rc_surface",
  nullif(r.data->'answers'->'rc'->>'safety','')::numeric as "rc_safety",
  nullif(r.data->'answers'->'rc'->>'scenery','')::numeric as "rc_scenery",
  nullif(r.data->'answers'->'rc'->>'purpose','')::numeric as "rc_purpose",
  nullif(r.data->'answers'->'rc'->>'familiar','')::numeric as "rc_familiar",
  nullif(r.data->'answers'->'rc'->>'visible','')::numeric as "rc_visible",
  nullif(r.data->'answers'->'rc'->>'people','')::numeric as "rc_people",
  nullif(r.data->'answers'->'env'->>'reroute','')::numeric as "env_reroute",
  nullif(r.data->'answers'->'env'->>'avoid','')::numeric as "env_avoid",
  nullif(r.data->'answers'->'env'->>'follow','')::numeric as "env_follow",
  case when jsonb_typeof(r.data->'answers'->'wrong_turns_10')='number' then (r.data->'answers'->'wrong_turns_10'#>>'{}')::numeric end as "wrong_turns_10",
  case when jsonb_typeof(r.data->'answers'->'wrong_turns_lm_10')='number' then (r.data->'answers'->'wrong_turns_lm_10'#>>'{}')::numeric end as "wrong_turns_lm_10",
  case when jsonb_typeof(r.data->'answers'->'detour_min')='number' then (r.data->'answers'->'detour_min'#>>'{}')::numeric end as "detour_min",
  case when jsonb_typeof(r.data->'answers'->'crowd_people')='number' then (r.data->'answers'->'crowd_people'#>>'{}')::numeric end as "crowd_people",
  case when jsonb_typeof(r.data->'answers'->'crowd_delay_min')='number' then (r.data->'answers'->'crowd_delay_min'#>>'{}')::numeric end as "crowd_delay_min",
  (select count(*) from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where not coalesce((t->>'skipped')::boolean,false)) as "n_walks",
  jsonb_array_length(case when jsonb_typeof(r.data->'answers'->'walks'->'ratings')='array' then r.data->'answers'->'walks'->'ratings' else '[]'::jsonb end) as "n_paths_rated",
  (select count(*) from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t cross join lateral jsonb_array_elements(case when jsonb_typeof(t->'landmarks')='array' then t->'landmarks' else '[]'::jsonb end) l) as "n_landmark_picks",
  (select count(*) from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where coalesce((t->>'landmarks_none')::boolean,false)) as "n_walks_no_landmark",
  (select string_agg(distinct l->>'id', '; ') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t cross join lateral jsonb_array_elements(case when jsonb_typeof(t->'landmarks')='array' then t->'landmarks' else '[]'::jsonb end) l) as "walk_landmark_ids",
  (select mode() within group (order by t->'details'->>'walk_time') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_time' is not null) as "walk_time_most",
  (select mode() within group (order by t->'details'->>'walk_minutes') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_minutes' is not null) as "walk_minutes_most",
  (select mode() within group (order by t->'details'->>'walk_knowledge') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_knowledge' is not null) as "walk_knowledge_most",
  (select mode() within group (order by t->'details'->>'walk_choice') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_choice' is not null) as "walk_choice_most",
  (select mode() within group (order by t->'details'->>'walk_crowd') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_crowd' is not null) as "walk_crowd_most",
  (select mode() within group (order by t->'details'->>'in_which_half_hour_do_you_us') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'in_which_half_hour_do_you_us' is not null) as "in_which_half_hour_do_you_us_most"
from public."campus_walks" r
order by r.respondent_no;
alter view public."campus_walks_respondents" set (security_invoker = true);
revoke all on public."campus_walks_respondents" from anon, authenticated;

-- 4b. Answers in words: one row per person, every question in order, the option text instead of its code.
create view public."campus_walks_answers" as
select
  'R' || lpad(r.respondent_no::text, 4, '0') as respondent_code,
  r.respondent_no,
  r.created_at as submitted_at,
  coalesce(case r.data->'answers'->>'age' when 'u18' then 'Under 18' when '18_21' then '18 to 21' when '22_25' then '22 to 25' when '26_35' then '26 to 35' when '36_50' then '36 to 50' when '50plus' then 'Over 50' end, r.data->'answers'->>'age') as "age",
  coalesce(case r.data->'answers'->>'sex' when 'f' then 'Female' when 'm' then 'Male' end, r.data->'answers'->>'sex') as "sex",
  coalesce(case r.data->'answers'->>'role' when 'ug' then 'Undergraduate student' when 'pg' then 'Postgraduate student' when 'academic' then 'Academic staff' when 'staff' then 'Administrative or support staff' when 'visitor' then 'Visitor' end, r.data->'answers'->>'role') as "role",
  coalesce(case r.data->'answers'->>'ug_stage' when 'y1' then 'Freshman: 1st year' when 'y2' then 'Sophomore: 2nd year' when 'y3' then 'Junior: 3rd year' when 'y4' then 'Senior: 4th year' when 'y5' then '5th year or above' end, r.data->'answers'->>'ug_stage') as "ug_stage",
  coalesce(case r.data->'answers'->>'pg_level' when 'diploma' then 'Diploma' when 'masters' then 'Master''s' when 'phd' then 'PhD' end, r.data->'answers'->>'pg_level') as "pg_level",
  coalesce(case r.data->'answers'->>'academic_rank' when 'ta' then 'Teaching assistant or demonstrator' when 'al' then 'Assistant lecturer' when 'lecturer' then 'Lecturer or assistant professor' when 'assoc' then 'Associate professor' when 'prof' then 'Professor' end, r.data->'answers'->>'academic_rank') as "academic_rank",
  coalesce(case r.data->'answers'->>'staff_type' when 'office' then 'Office or administrative work' when 'technical' then 'Technical or laboratory work' when 'facilities' then 'Facilities, maintenance or cleaning' when 'security' then 'Security' when 'service' then 'Food or retail service' end, r.data->'answers'->>'staff_type') as "staff_type",
  coalesce(case r.data->'answers'->>'visit_purpose' when 'prospective' then 'Prospective student' when 'event' then 'Event, conference or exhibition' when 'business' then 'Business or meeting' when 'service' then 'A service (office, clinic, bank)' when 'companion' then 'Accompanying someone' when 'family' then 'family' end, r.data->'answers'->>'visit_purpose') as "visit_purpose",
  coalesce(case r.data->'answers'->>'qualification' when 'secondary' then 'Secondary school or equivalent' when 'diploma' then 'Diploma' when 'bachelor' then 'Bachelor''s degree' when 'master' then 'Master''s degree' when 'doctorate' then 'Doctorate' when 'none' then 'None' end, r.data->'answers'->>'qualification') as "qualification",
  r.data->'answers'->>'programme' as "programme",
  r.data->'answers'->>'which_programme_are_you_stud' as "which_programme_are_you_stud",
  r.data->'answers'->>'which_faculty_or_building_do' as "which_faculty_or_building_do",
  coalesce(case r.data->'answers'->>'arrival_mode' when 'walk' then 'Walking' when 'bike' then 'Bicycle or scooter' when 'bus' then 'Bus or minibus' when 'car' then 'Car' when 'taxi' then 'Ride-hailing or taxi' end, r.data->'answers'->>'arrival_mode') as "arrival_mode",
  coalesce(case r.data->'answers'->>'arrival_clock' when '05:00' then '05:00 – 05:30' when '05:30' then '05:30 – 06:00' when '06:00' then '06:00 – 06:30' when '06:30' then '06:30 – 07:00' when '07:00' then '07:00 – 07:30' when '07:30' then '07:30 – 08:00' when '08:00' then '08:00 – 08:30' when '08:30' then '08:30 – 09:00' when '09:00' then '09:00 – 09:30' when '09:30' then '09:30 – 10:00' when '10:00' then '10:00 – 10:30' when '10:30' then '10:30 – 11:00' when '11:00' then '11:00 – 11:30' when '11:30' then '11:30 – 12:00' when '12:00' then '12:00 – 12:30' when '12:30' then '12:30 – 13:00' when '13:00' then '13:00 – 13:30' when '13:30' then '13:30 – 14:00' when '14:00' then '14:00 – 14:30' when '14:30' then '14:30 – 15:00' when '15:00' then '15:00 – 15:30' when '15:30' then '15:30 – 16:00' when '16:00' then '16:00 – 16:30' when '16:30' then '16:30 – 17:00' when '17:00' then '17:00 – 17:30' when '17:30' then '17:30 – 18:00' when '18:00' then '18:00 – 18:30' when '18:30' then '18:30 – 19:00' when '19:00' then '19:00 – 19:30' when '19:30' then '19:30 – 20:00' when '20:00' then '20:00 – 20:30' when '20:30' then '20:30 – 21:00' when '21:00' then '21:00 – 21:30' when '21:30' then '21:30 – 22:00' when '22:00' then '22:00 – 22:30' when '22:30' then '22:30 – 23:00' end, r.data->'answers'->>'arrival_clock') as "arrival_clock",
  coalesce(case r.data->'answers'->>'leave_clock' when '05:00' then '05:00 – 05:30' when '05:30' then '05:30 – 06:00' when '06:00' then '06:00 – 06:30' when '06:30' then '06:30 – 07:00' when '07:00' then '07:00 – 07:30' when '07:30' then '07:30 – 08:00' when '08:00' then '08:00 – 08:30' when '08:30' then '08:30 – 09:00' when '09:00' then '09:00 – 09:30' when '09:30' then '09:30 – 10:00' when '10:00' then '10:00 – 10:30' when '10:30' then '10:30 – 11:00' when '11:00' then '11:00 – 11:30' when '11:30' then '11:30 – 12:00' when '12:00' then '12:00 – 12:30' when '12:30' then '12:30 – 13:00' when '13:00' then '13:00 – 13:30' when '13:30' then '13:30 – 14:00' when '14:00' then '14:00 – 14:30' when '14:30' then '14:30 – 15:00' when '15:00' then '15:00 – 15:30' when '15:30' then '15:30 – 16:00' when '16:00' then '16:00 – 16:30' when '16:30' then '16:30 – 17:00' when '17:00' then '17:00 – 17:30' when '17:30' then '17:30 – 18:00' when '18:00' then '18:00 – 18:30' when '18:30' then '18:30 – 19:00' when '19:00' then '19:00 – 19:30' when '19:30' then '19:30 – 20:00' when '20:00' then '20:00 – 20:30' when '20:30' then '20:30 – 21:00' when '21:00' then '21:00 – 21:30' when '21:30' then '21:30 – 22:00' when '22:00' then '22:00 – 22:30' when '22:30' then '22:30 – 23:00' end, r.data->'answers'->>'leave_clock') as "leave_clock",
  coalesce(case r.data->'answers'->>'days_per_week' when 'd0' then 'Less than once a week' when 'd1' then '1 day' when 'd2' then '2 to 3 days' when 'd4' then '4 to 5 days' when 'd6' then '6 to 7 days' end, r.data->'answers'->>'days_per_week') as "days_per_week",
  coalesce(case r.data->'answers'->>'walks_per_day' when 'w1' then '1 or 2' when 'w3' then '3 or 4' when 'w5' then '5 or 6' when 'w7' then '7 or more' end, r.data->'answers'->>'walks_per_day') as "walks_per_day",
  coalesce(case r.data->'answers'->>'walk_company' when 'g1' then 'Alone' when 'g2' then 'With one other person' when 'g3' then 'In a group of three or more' end, r.data->'answers'->>'walk_company') as "walk_company",
  coalesce(case r.data->'answers'->>'walk_pace' when 'slow' then 'Slow, I take my time' when 'average' then 'Average' when 'fast' then 'Fast, I walk briskly' end, r.data->'answers'->>'walk_pace') as "walk_pace",
  (select string_agg(coalesce(case x when 'greenery' then 'Trees and greenery' when 'facades' then 'Building facades' when 'signs' then 'Signs' when 'art' then 'Artworks or monuments' when 'people' then 'People and activity' when 'views' then 'Open views and sky' when 'shade' then 'Shade structures' when 'water' then 'Water features' end, x), '; ' order by o) from jsonb_array_elements_text(case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end) with ordinality as y(x,o)) as "visual_features",
  coalesce(case r.data->'answers'->'legibility'->>'leg1' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'legibility'->>'leg1') as "legibility_leg1",
  coalesce(case r.data->'answers'->'legibility'->>'leg2' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'legibility'->>'leg2') as "legibility_leg2",
  coalesce(case r.data->'answers'->'legibility'->>'int1' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'legibility'->>'int1') as "legibility_int1",
  coalesce(case r.data->'answers'->'legibility'->>'int2' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'legibility'->>'int2') as "legibility_int2",
  coalesce(case r.data->'answers'->'lrs'->>'lost' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'lrs'->>'lost') as "lrs_lost",
  coalesce(case r.data->'answers'->'lrs'->>'l1' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'lrs'->>'l1') as "lrs_l1",
  coalesce(case r.data->'answers'->'lrs'->>'l2' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'lrs'->>'l2') as "lrs_l2",
  coalesce(case r.data->'answers'->'lrs'->>'r1' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'lrs'->>'r1') as "lrs_r1",
  coalesce(case r.data->'answers'->'lrs'->>'r2' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'lrs'->>'r2') as "lrs_r2",
  coalesce(case r.data->'answers'->'lrs'->>'s1' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'lrs'->>'s1') as "lrs_s1",
  coalesce(case r.data->'answers'->'lrs'->>'s2' when '1' then 'Strongly disagree' when '2' then 'Disagree' when '3' then 'Neither agree nor disagree' when '4' then 'Agree' when '5' then 'Strongly agree' end, r.data->'answers'->'lrs'->>'s2') as "lrs_s2",
  coalesce(case r.data->'answers'->'cue'->>'signs' when '1' then 'Never' when '2' then 'Rarely' when '3' then 'Sometimes' when '4' then 'Often' when '5' then 'Always' end, r.data->'answers'->'cue'->>'signs') as "cue_signs",
  coalesce(case r.data->'answers'->'cue'->>'landmarks' when '1' then 'Never' when '2' then 'Rarely' when '3' then 'Sometimes' when '4' then 'Often' when '5' then 'Always' end, r.data->'answers'->'cue'->>'landmarks') as "cue_landmarks",
  coalesce(case r.data->'answers'->'cue'->>'maps' when '1' then 'Never' when '2' then 'Rarely' when '3' then 'Sometimes' when '4' then 'Often' when '5' then 'Always' end, r.data->'answers'->'cue'->>'maps') as "cue_maps",
  coalesce(case r.data->'answers'->'cue'->>'people' when '1' then 'Never' when '2' then 'Rarely' when '3' then 'Sometimes' when '4' then 'Often' when '5' then 'Always' end, r.data->'answers'->'cue'->>'people') as "cue_people",
  coalesce(case r.data->'answers'->'cue'->>'memory' when '1' then 'Never' when '2' then 'Rarely' when '3' then 'Sometimes' when '4' then 'Often' when '5' then 'Always' end, r.data->'answers'->'cue'->>'memory') as "cue_memory",
  coalesce(case r.data->'answers'->'rc'->>'distance' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'distance') as "rc_distance",
  coalesce(case r.data->'answers'->'rc'->>'angular' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'angular') as "rc_angular",
  coalesce(case r.data->'answers'->'rc'->>'turns' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'turns') as "rc_turns",
  coalesce(case r.data->'answers'->'rc'->>'shade' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'shade') as "rc_shade",
  coalesce(case r.data->'answers'->'rc'->>'surface' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'surface') as "rc_surface",
  coalesce(case r.data->'answers'->'rc'->>'safety' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'safety') as "rc_safety",
  coalesce(case r.data->'answers'->'rc'->>'scenery' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'scenery') as "rc_scenery",
  coalesce(case r.data->'answers'->'rc'->>'purpose' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'purpose') as "rc_purpose",
  coalesce(case r.data->'answers'->'rc'->>'familiar' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'familiar') as "rc_familiar",
  coalesce(case r.data->'answers'->'rc'->>'visible' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'visible') as "rc_visible",
  coalesce(case r.data->'answers'->'rc'->>'people' when '1' then 'Not at all' when '2' then 'Slightly' when '3' then 'Moderately' when '4' then 'Very much' when '5' then 'Completely' end, r.data->'answers'->'rc'->>'people') as "rc_people",
  coalesce(case r.data->'answers'->'env'->>'reroute' when '1' then 'Never' when '2' then 'Rarely' when '3' then 'Sometimes' when '4' then 'Often' when '5' then 'Always' end, r.data->'answers'->'env'->>'reroute') as "env_reroute",
  coalesce(case r.data->'answers'->'env'->>'avoid' when '1' then 'Never' when '2' then 'Rarely' when '3' then 'Sometimes' when '4' then 'Often' when '5' then 'Always' end, r.data->'answers'->'env'->>'avoid') as "env_avoid",
  coalesce(case r.data->'answers'->'env'->>'follow' when '1' then 'Never' when '2' then 'Rarely' when '3' then 'Sometimes' when '4' then 'Often' when '5' then 'Always' end, r.data->'answers'->'env'->>'follow') as "env_follow",
  case when jsonb_typeof(r.data->'answers'->'wrong_turns_10')='number' then (r.data->'answers'->'wrong_turns_10'#>>'{}')::numeric end as "wrong_turns_10",
  case when jsonb_typeof(r.data->'answers'->'wrong_turns_lm_10')='number' then (r.data->'answers'->'wrong_turns_lm_10'#>>'{}')::numeric end as "wrong_turns_lm_10",
  case when jsonb_typeof(r.data->'answers'->'detour_min')='number' then (r.data->'answers'->'detour_min'#>>'{}')::numeric end as "detour_min",
  case when jsonb_typeof(r.data->'answers'->'crowd_people')='number' then (r.data->'answers'->'crowd_people'#>>'{}')::numeric end as "crowd_people",
  case when jsonb_typeof(r.data->'answers'->'crowd_delay_min')='number' then (r.data->'answers'->'crowd_delay_min'#>>'{}')::numeric end as "crowd_delay_min",
  (select count(*) from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where not coalesce((t->>'skipped')::boolean,false)) as "walks_n_walks",
  jsonb_array_length(case when jsonb_typeof(r.data->'answers'->'walks'->'ratings')='array' then r.data->'answers'->'walks'->'ratings' else '[]'::jsonb end) as "walks_n_paths_rated",
  (select string_agg(distinct l->>'name', '; ') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t cross join lateral jsonb_array_elements(case when jsonb_typeof(t->'landmarks')='array' then t->'landmarks' else '[]'::jsonb end) l) as "walks_landmarks_used",
  coalesce(case (select mode() within group (order by t->'details'->>'walk_time') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_time' is not null) when '05:00' then '05:00 – 05:30' when '05:30' then '05:30 – 06:00' when '06:00' then '06:00 – 06:30' when '06:30' then '06:30 – 07:00' when '07:00' then '07:00 – 07:30' when '07:30' then '07:30 – 08:00' when '08:00' then '08:00 – 08:30' when '08:30' then '08:30 – 09:00' when '09:00' then '09:00 – 09:30' when '09:30' then '09:30 – 10:00' when '10:00' then '10:00 – 10:30' when '10:30' then '10:30 – 11:00' when '11:00' then '11:00 – 11:30' when '11:30' then '11:30 – 12:00' when '12:00' then '12:00 – 12:30' when '12:30' then '12:30 – 13:00' when '13:00' then '13:00 – 13:30' when '13:30' then '13:30 – 14:00' when '14:00' then '14:00 – 14:30' when '14:30' then '14:30 – 15:00' when '15:00' then '15:00 – 15:30' when '15:30' then '15:30 – 16:00' when '16:00' then '16:00 – 16:30' when '16:30' then '16:30 – 17:00' when '17:00' then '17:00 – 17:30' when '17:30' then '17:30 – 18:00' when '18:00' then '18:00 – 18:30' when '18:30' then '18:30 – 19:00' when '19:00' then '19:00 – 19:30' when '19:30' then '19:30 – 20:00' when '20:00' then '20:00 – 20:30' when '20:30' then '20:30 – 21:00' when '21:00' then '21:00 – 21:30' when '21:30' then '21:30 – 22:00' when '22:00' then '22:00 – 22:30' when '22:30' then '22:30 – 23:00' end, (select mode() within group (order by t->'details'->>'walk_time') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_time' is not null)) as "walk_time_most",
  (select mode() within group (order by t->'details'->>'walk_minutes') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_minutes' is not null) as "walk_minutes_most",
  coalesce(case (select mode() within group (order by t->'details'->>'walk_knowledge') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_knowledge' is not null) when 'landmark' then 'I followed landmarks I recognise along the way' when 'route' then 'I know the sequence of turns by heart' when 'survey' then 'I picture the campus layout like a map in my head' when 'aided' then 'I followed signs, a map or other people' end, (select mode() within group (order by t->'details'->>'walk_knowledge') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_knowledge' is not null)) as "walk_knowledge_most",
  coalesce(case (select mode() within group (order by t->'details'->>'walk_choice') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_choice' is not null) when 'distance' then 'It is the shortest distance' when 'least_angle' then 'It keeps the straightest direction' when 'fewest_turns' then 'It has the fewest turns' when 'comfort' then 'It is shaded and comfortable to walk' when 'safety' then 'It feels safe' when 'scenery' then 'It has pleasant views and greenery' when 'purpose' then 'It passes places I need for work or study' when 'familiar' then 'It is the route I already know' when 'adaptive' then 'It changes depending on the situation' end, (select mode() within group (order by t->'details'->>'walk_choice') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_choice' is not null)) as "walk_choice_most",
  coalesce(case (select mode() within group (order by t->'details'->>'walk_crowd') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_crowd' is not null) when 'keep' then 'I keep to my route and walk through' when 'avoid' then 'I keep my distance or take another path to avoid the crowd' when 'follow' then 'I follow the flow of other people' when 'open' then 'I move towards open spaces where I can see ahead' end, (select mode() within group (order by t->'details'->>'walk_crowd') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_crowd' is not null)) as "walk_crowd_most",
  coalesce(case (select mode() within group (order by t->'details'->>'in_which_half_hour_do_you_us') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'in_which_half_hour_do_you_us' is not null) when 'Option 1' then 'Option 1' when 'Option 2' then 'Option 2' end, (select mode() within group (order by t->'details'->>'in_which_half_hour_do_you_us') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'in_which_half_hour_do_you_us' is not null)) as "in_which_half_hour_do_you_us_most"
from public."campus_walks" r
order by r.respondent_no;
alter view public."campus_walks_answers" set (security_invoker = true);
revoke all on public."campus_walks_answers" from anon, authenticated;

-- 5. Agent personas: one row per respondent, one column per agent attribute
--    (attributes named in the Designer; several statements with the same name are averaged).
--    (created after the routes view, see below)
-- 6. Routes: one row per walk, segments in walking order, WKT line in the CRS of your shapefile (unknown).
--    QGIS: Layer > Add Layer > Add Delimited Text Layer > Geometry definition: WKT, field "wkt".
create view public."campus_walks_route_segments" as
select
  'R' || lpad(r.respondent_no::text, 4, '0') as respondent_code,
  r.respondent_no,
  t.ord::int as walk_no,
  t.trip->>'period' as walk_period,
  x.o::int as step_no,
  x.s->>'id' as segment_id,
  x.s->>'from' as from_node,
  x.s->>'to' as to_node,
  case when g.from_node = x.s->>'from' then 'forward' else 'reverse' end as direction,
  g.length_m,
  'LINESTRING(' || case when g.from_node = x.s->>'from' then g.coords_ab else g.coords_ba end || ')' as wkt
from public."campus_walks" r
cross join lateral jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) with ordinality as t(trip, ord)
cross join lateral jsonb_array_elements(case when jsonb_typeof(t.trip->'segments')='array' then t.trip->'segments' else '[]'::jsonb end) with ordinality as x(s, o)
left join public."campus_walks_segments" g on g.segment_id = x.s->>'id'
order by r.respondent_no, walk_no, step_no;
alter view public."campus_walks_route_segments" set (security_invoker = true);
revoke all on public."campus_walks_route_segments" from anon, authenticated;

create view public."campus_walks_routes" as
select
  'R' || lpad(r.respondent_no::text, 4, '0') as respondent_code,
  r.respondent_no,
  t.ord::int as walk_no,
  t.trip->>'period' as walk_period,
  t.trip->>'period_label' as walk_label,
  t.trip->'details'->>'walk_time' as "walk_time",
  t.trip->'details'->>'walk_minutes' as "walk_minutes",
  t.trip->'details'->>'walk_knowledge' as "walk_knowledge",
  t.trip->'details'->>'walk_choice' as "walk_choice",
  t.trip->'details'->>'walk_crowd' as "walk_crowd",
  t.trip->'details'->>'in_which_half_hour_do_you_us' as "in_which_half_hour_do_you_us",
  coalesce((t.trip->>'skipped')::boolean, false) as skipped,
  t.trip->'origin'->>'id' as origin_id,
  t.trip->'origin'->>'name' as origin_name,
  t.trip->'destination'->>'id' as destination_id,
  t.trip->'destination'->>'name' as destination_name,
  coalesce((t.trip->>'landmarks_none')::boolean, false) as no_landmarks,
  jsonb_array_length(case when jsonb_typeof(t.trip->'landmarks')='array' then t.trip->'landmarks' else '[]'::jsonb end) as n_landmarks,
  (select string_agg(l.lm->>'id', ';' order by l.o) from jsonb_array_elements(case when jsonb_typeof(t.trip->'landmarks')='array' then t.trip->'landmarks' else '[]'::jsonb end) with ordinality as l(lm, o)) as landmark_ids,
  (select string_agg(l.lm->>'name', '; ' order by l.o) from jsonb_array_elements(case when jsonb_typeof(t.trip->'landmarks')='array' then t.trip->'landmarks' else '[]'::jsonb end) with ordinality as l(lm, o)) as landmark_names,
  jsonb_array_length(case when jsonb_typeof(t.trip->'segments')='array' then t.trip->'segments' else '[]'::jsonb end) as n_segments,
  (select round(sum(g.length_m), 1) from jsonb_array_elements(case when jsonb_typeof(t.trip->'segments')='array' then t.trip->'segments' else '[]'::jsonb end) as x(s) join public."campus_walks_segments" g on g.segment_id = x.s->>'id') as length_m,
  (select string_agg(x.s->>'id', ';' order by x.o) from jsonb_array_elements(case when jsonb_typeof(t.trip->'segments')='array' then t.trip->'segments' else '[]'::jsonb end) with ordinality as x(s, o)) as segment_ids,
  (select 'LINESTRING(' || string_agg(case when x.o = 1 then (case when g.from_node = x.s->>'from' then g.coords_ab else g.coords_ba end) else (case when g.from_node = x.s->>'from' then g.coords_ab_tail else g.coords_ba_tail end) end, ', ' order by x.o) || ')'
     from jsonb_array_elements(case when jsonb_typeof(t.trip->'segments')='array' then t.trip->'segments' else '[]'::jsonb end) with ordinality as x(s, o) join public."campus_walks_segments" g on g.segment_id = x.s->>'id') as wkt
from public."campus_walks" r
cross join lateral jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) with ordinality as t(trip, ord)
order by r.respondent_no, walk_no;
alter view public."campus_walks_routes" set (security_invoker = true);
revoke all on public."campus_walks_routes" from anon, authenticated;

-- 7. Path ratings: one row per person per rated path (1 = strongly disagree ... 5 = strongly agree).
create view public."campus_walks_path_ratings" as
select
  'R' || lpad(r.respondent_no::text, 4, '0') as respondent_code,
  r.respondent_no,
  g.rt->>'segment' as segment_id,
  g.rt->>'from' as from_node,
  g.rt->>'to' as to_node,
  g.rt->>'first_trip' as first_walk,
  case when jsonb_typeof(g.rt->'scores'->'pleasant')='number' then (g.rt->'scores'->'pleasant'#>>'{}')::numeric end as "pleasant",
  case when jsonb_typeof(g.rt->'scores'->'memorable')='number' then (g.rt->'scores'->'memorable'#>>'{}')::numeric end as "memorable",
  case when jsonb_typeof(g.rt->'scores'->'comfort')='number' then (g.rt->'scores'->'comfort'#>>'{}')::numeric end as "comfort",
  case when jsonb_typeof(g.rt->'scores'->'safe')='number' then (g.rt->'scores'->'safe'#>>'{}')::numeric end as "safe"
from public."campus_walks" r
cross join lateral jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'ratings')='array' then r.data->'answers'->'walks'->'ratings' else '[]'::jsonb end) as g(rt)
order by r.respondent_no, segment_id;
alter view public."campus_walks_path_ratings" set (security_invoker = true);
revoke all on public."campus_walks_path_ratings" from anon, authenticated;

-- 8. Mean ratings per segment (all segments, unused ones have n_raters = 0), with geometry.
create view public."campus_walks_segment_means" as
select
  s.segment_id,
  s.segment_name,
  s.length_m,
  (select count(*) from public."campus_walks_route_segments" f where f.segment_id = s.segment_id) as n_traversals,
  count(pr.respondent_no) as n_raters,
  round(avg(pr."pleasant"), 2) as "mean_pleasant",
  round(stddev_samp(pr."pleasant"), 2) as "sd_pleasant",
  round(avg(pr."memorable"), 2) as "mean_memorable",
  round(stddev_samp(pr."memorable"), 2) as "sd_memorable",
  round(avg(pr."comfort"), 2) as "mean_comfort",
  round(stddev_samp(pr."comfort"), 2) as "sd_comfort",
  round(avg(pr."safe"), 2) as "mean_safe",
  round(stddev_samp(pr."safe"), 2) as "sd_safe",
  s.wkt
from public."campus_walks_segments" s
left join public."campus_walks_path_ratings" pr on pr.segment_id = s.segment_id
group by s.segment_id, s.segment_name, s.length_m, s.wkt
order by s.segment_id;
alter view public."campus_walks_segment_means" set (security_invoker = true);
revoke all on public."campus_walks_segment_means" from anon, authenticated;

-- 9. Mean of each person's path ratings.
create view public."campus_walks_respondent_means" as
select
  respondent_code,
  respondent_no,
  count(*) as n_paths_rated,
  round(avg("pleasant"), 2) as "mean_pleasant",
  round(avg("memorable"), 2) as "mean_memorable",
  round(avg("comfort"), 2) as "mean_comfort",
  round(avg("safe"), 2) as "mean_safe"
from public."campus_walks_path_ratings"
group by respondent_code, respondent_no
order by respondent_no;
alter view public."campus_walks_respondent_means" set (security_invoker = true);
revoke all on public."campus_walks_respondent_means" from anon, authenticated;

-- 9b. Landmarks used on each walk: one row per landmark, in the order the person passed them.
--     near_step = step of the route (route_segments.step_no) closest to the landmark; dist_m = its distance in metres.
create view public."campus_walks_route_landmarks" as
select
  'R' || lpad(r.respondent_no::text, 4, '0') as respondent_code,
  r.respondent_no,
  t.ord::int as walk_no,
  t.trip->>'period' as walk_period,
  l.o::int as pick_no,
  l.lm->>'id' as landmark_id,
  coalesce(k.landmark_name, l.lm->>'name') as landmark_name,
  nullif(l.lm->>'near_step', '')::int as near_step,
  l.lm->>'near_segment' as near_segment_id,
  nullif(l.lm->>'dist_m', '')::numeric as dist_m,
  k.wkt
from public."campus_walks" r
cross join lateral jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) with ordinality as t(trip, ord)
cross join lateral jsonb_array_elements(case when jsonb_typeof(t.trip->'landmarks')='array' then t.trip->'landmarks' else '[]'::jsonb end) with ordinality as l(lm, o)
left join public."campus_walks_landmarks" k on k.landmark_id = l.lm->>'id'
order by r.respondent_no, walk_no, pick_no;
alter view public."campus_walks_route_landmarks" set (security_invoker = true);
revoke all on public."campus_walks_route_landmarks" from anon, authenticated;

-- 9c. Use of each landmark: on walks (9b) and in questions that pick from the Landmarks layer.
create view public."campus_walks_landmark_use" as
select
  k.landmark_id,
  k.landmark_name,
  (select count(*) from public."campus_walks_route_landmarks" u where u.landmark_id = k.landmark_id) as n_walk_uses,
  (select count(distinct u.respondent_no) from public."campus_walks_route_landmarks" u where u.landmark_id = k.landmark_id) as n_people_on_walks,
  (select round(avg(u.dist_m), 1) from public."campus_walks_route_landmarks" u where u.landmark_id = k.landmark_id) as mean_dist_m,
  k.wkt
from public."campus_walks_landmarks" k
order by k.landmark_id;
alter view public."campus_walks_landmark_use" set (security_invoker = true);
revoke all on public."campus_walks_landmark_use" from anon, authenticated;

-- 10. Agent personas (see 5).
create view public."campus_walks_agents" as
select
  'R' || lpad(r.respondent_no::text, 4, '0') as respondent_code,
  r.data->'answers'->>'age' as "age_group",
  r.data->'answers'->>'sex' as "sex",
  r.data->'answers'->>'role' as "role",
  concat_ws('; ', r.data->'answers'->>'ug_stage', r.data->'answers'->>'pg_level', r.data->'answers'->>'academic_rank', r.data->'answers'->>'staff_type', r.data->'answers'->>'visit_purpose') as "role_subtype",
  r.data->'answers'->>'qualification' as "education",
  concat_ws('; ', r.data->'answers'->>'programme', r.data->'answers'->>'which_programme_are_you_stud') as "programme",
  r.data->'answers'->>'arrival_mode' as "entry_mode",
  r.data->'answers'->>'arrival_clock' as "arrival_clock",
  r.data->'answers'->>'leave_clock' as "departure_clock",
  r.data->'answers'->>'days_per_week' as "visit_frequency",
  r.data->'answers'->>'walks_per_day' as "trips_per_day",
  r.data->'answers'->>'walk_company' as "group_size",
  r.data->'answers'->>'walk_pace' as "walking_speed",
  (select string_agg(x, '; ') from jsonb_array_elements_text(case when jsonb_typeof(r.data->'answers'->'visual_features')='array' then r.data->'answers'->'visual_features' else '[]'::jsonb end) as x) as "perc_visual_features",
  (select round(avg(v), 2) from (values (nullif(r.data->'answers'->'legibility'->>'leg1','')::numeric), (nullif(r.data->'answers'->'legibility'->>'leg2','')::numeric)) as z(v)) as "cog_legibility",
  (select round(avg(v), 2) from (values (nullif(r.data->'answers'->'legibility'->>'int1','')::numeric), (nullif(r.data->'answers'->'legibility'->>'int2','')::numeric)) as z(v)) as "cog_intelligibility",
  nullif(r.data->'answers'->'lrs'->>'lost','')::numeric as "wayfinding_ability",
  (select round(avg(v), 2) from (values (nullif(r.data->'answers'->'lrs'->>'l1','')::numeric), (nullif(r.data->'answers'->'lrs'->>'l2','')::numeric)) as z(v)) as "know_landmark",
  (select round(avg(v), 2) from (values (nullif(r.data->'answers'->'lrs'->>'r1','')::numeric), (nullif(r.data->'answers'->'lrs'->>'r2','')::numeric)) as z(v)) as "know_route",
  (select round(avg(v), 2) from (values (nullif(r.data->'answers'->'lrs'->>'s1','')::numeric), (nullif(r.data->'answers'->'lrs'->>'s2','')::numeric)) as z(v)) as "know_survey",
  nullif(r.data->'answers'->'cue'->>'signs','')::numeric as "cue_signs",
  nullif(r.data->'answers'->'cue'->>'landmarks','')::numeric as "cue_landmarks",
  nullif(r.data->'answers'->'cue'->>'maps','')::numeric as "cue_maps",
  nullif(r.data->'answers'->'cue'->>'people','')::numeric as "cue_people",
  nullif(r.data->'answers'->'cue'->>'memory','')::numeric as "cue_memory",
  nullif(r.data->'answers'->'rc'->>'distance','')::numeric as "rc_distance",
  nullif(r.data->'answers'->'rc'->>'angular','')::numeric as "rc_least_angle",
  nullif(r.data->'answers'->'rc'->>'turns','')::numeric as "rc_fewest_turns",
  nullif(r.data->'answers'->'rc'->>'shade','')::numeric as "rc_shade",
  nullif(r.data->'answers'->'rc'->>'surface','')::numeric as "rc_surface",
  nullif(r.data->'answers'->'rc'->>'safety','')::numeric as "rc_safety",
  nullif(r.data->'answers'->'rc'->>'scenery','')::numeric as "rc_scenery",
  nullif(r.data->'answers'->'rc'->>'purpose','')::numeric as "rc_purpose",
  nullif(r.data->'answers'->'rc'->>'familiar','')::numeric as "rc_familiar",
  nullif(r.data->'answers'->'rc'->>'visible','')::numeric as "env_visibility",
  nullif(r.data->'answers'->'rc'->>'people','')::numeric as "env_attraction_people",
  nullif(r.data->'answers'->'env'->>'reroute','')::numeric as "rc_rerouting",
  nullif(r.data->'answers'->'env'->>'avoid','')::numeric as "env_crowd_avoid",
  nullif(r.data->'answers'->'env'->>'follow','')::numeric as "env_herding",
  case when jsonb_typeof(r.data->'answers'->'wrong_turns_10')='number' then (r.data->'answers'->'wrong_turns_10'#>>'{}')::numeric end as "wrong_turns_per_10_walks",
  case when jsonb_typeof(r.data->'answers'->'wrong_turns_lm_10')='number' then (r.data->'answers'->'wrong_turns_lm_10'#>>'{}')::numeric end as "wrong_turns_per_10_walks_landmark",
  case when jsonb_typeof(r.data->'answers'->'detour_min')='number' then (r.data->'answers'->'detour_min'#>>'{}')::numeric end as "detour_tolerance_min",
  case when jsonb_typeof(r.data->'answers'->'crowd_people')='number' then (r.data->'answers'->'crowd_people'#>>'{}')::numeric end as "crowd_threshold_people",
  case when jsonb_typeof(r.data->'answers'->'crowd_delay_min')='number' then (r.data->'answers'->'crowd_delay_min'#>>'{}')::numeric end as "crowd_slowdown_min",
  (select string_agg(distinct l->>'id', '; ') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t cross join lateral jsonb_array_elements(case when jsonb_typeof(t->'landmarks')='array' then t->'landmarks' else '[]'::jsonb end) l) as "route_landmarks",
  (select mode() within group (order by t->'details'->>'walk_time') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_time' is not null) as "walk_start_time",
  (select mode() within group (order by t->'details'->>'walk_minutes') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_minutes' is not null) as "walk_duration_min",
  (select mode() within group (order by t->'details'->>'walk_knowledge') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_knowledge' is not null) as "walk_knowledge_strategy",
  (select mode() within group (order by t->'details'->>'walk_choice') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_choice' is not null) as "walk_route_choice",
  (select mode() within group (order by t->'details'->>'walk_crowd') from jsonb_array_elements(case when jsonb_typeof(r.data->'answers'->'walks'->'trips')='array' then r.data->'answers'->'walks'->'trips' else '[]'::jsonb end) t where t->'details'->>'walk_crowd' is not null) as "walk_env_response",
  (select count(*) from public."campus_walks_routes" w where w.respondent_no = r.respondent_no and not w.skipped) as "n_walks"
from public."campus_walks" r
order by r.respondent_no;
alter view public."campus_walks_agents" set (security_invoker = true);
revoke all on public."campus_walks_agents" from anon, authenticated;

-- Done. Table Editor now lists "campus_walks" and the views starting with "campus_walks_".
